 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))

    def edge_segment(r):
        cells = [(c, g[r][c]) for c in range(w) if g[r][c] != bg]
        if not cells:
            return None
        color = cells[0][1]
        cols = [c for c, v in cells if v == color]
        return color, min(cols), max(cols)

    top, bottom = edge_segment(0), edge_segment(h - 1)
    if top is None or bottom is None or top[0] != bottom[0]:
        return g
    edge_color = top[0]
    marker_colors = [v for v in set(v for row in g for v in row)
                     if v not in (bg, edge_color)]
    if not marker_colors:
        return g
    marker_color = min(marker_colors, key=lambda v: sum(row.count(v) for row in g))
    markers = [(r, c) for r in range(h) for c in range(w) if g[r][c] == marker_color]

    tc, ts, te = top
    bc, bs, be = bottom
    top_len, bottom_len = te - ts + 1, be - bs + 1
    offsets = set()
    for r, c in markers:
        if ts <= c <= te:
            offsets.add(c - ts)
        if bs <= c <= be:
            offsets.add(c - bs)

    marker_set = set(markers)
    for off in offsets:
        if off < top_len:
            c = ts + off
            for r in range(1, h):
                if (r, c) in marker_set:
                    g[r][c] = 4
                    break
                if g[r][c] == bg:
                    g[r][c] = marker_color
        if off < bottom_len:
            c = bs + off
            for r in range(h - 2, -1, -1):
                if (r, c) in marker_set:
                    g[r][c] = 4
                    break
                if g[r][c] == bg:
                    g[r][c] = marker_color

    for r, c in markers:
        g[r][c] = 4
    return g
