 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    background = max({v for row in g for v in row}, key=lambda v: sum(row.count(v) for row in g))

    # Find the two matching marker-colored border bars.
    def edge_run(values):
        occupied = [i for i, value in enumerate(values) if value != background]
        if not occupied:
            return None
        color = values[occupied[0]]
        if any(values[i] != color for i in occupied):
            return None
        return color, min(occupied), max(occupied)

    top = edge_run(g[0])
    bottom = edge_run(g[-1])
    left = edge_run([g[r][0] for r in range(h)])
    right = edge_run([g[r][-1] for r in range(h)])

    if top and bottom and top[0] == bottom[0]:
        horizontal, bars = True, (top, bottom)
    elif left and right and left[0] == right[0]:
        horizontal, bars = False, (left, right)
    else:
        return g

    bar_color = bars[0][0]
    other_colors = [v for row in g for v in row if v != background and v != bar_color]
    if not other_colors:
        return g
    marker_color = min(set(other_colors), key=lambda v: sum(row.count(v) for row in g))
    markers = [(r, c) for r in range(h) for c in range(w) if g[r][c] == marker_color]

    # Each bar supplies an offset coordinate for an inward ray. The sparse
    # marks are endpoints/obstacles on the rays: paint through the field with
    # marker_color, and mark original points with 4.
    offsets = set()
    for r, c in markers:
        pos = c if horizontal else r
        for _, lo, hi in bars:
            if lo <= pos <= hi:
                offsets.add(pos - lo)

    for offset in offsets:
        for side, (_, lo, hi) in enumerate(bars):
            pos = lo + offset
            if pos > hi:
                continue
            if horizontal:
                rrng = range(1, h) if side == 0 else range(h - 2, -1, -1)
                for r in rrng:
                    if g[r][pos] == marker_color:
                        g[r][pos] = 4
                        break
                    if g[r][pos] == background:
                        g[r][pos] = marker_color
            else:
                crng = range(1, w) if side == 0 else range(w - 2, -1, -1)
                for c in crng:
                    if g[pos][c] == marker_color:
                        g[pos][c] = 4
                        break
                    if g[pos][c] == background:
                        g[pos][c] = marker_color

    for r, c in markers:
        g[r][c] = 4
    return g


