        axis = c if horizontal else r
        for _, start, end in bars:
            if start <= axis <= end:
                offsets.add(axis - start)

    for offset in offsets:
        for _, start, end in bars:
            axis = start + offset
            if axis > end:
                continue
            if horizontal:
                for r in range(1, h - 1):
                    if (r, axis) in markers:
                        g[r][axis] = 4
                    elif g[r][axis] == background:
                        g[r][axis] = marker_color
            else:
                for c in range(1, w - 1):
                    if (axis, c) in markers:
                        g[axis][c] = 4
                    elif g[axis][c] == background:
                        g[axis][c] = marker_color

    for r, c in markers:
        g[r][c] = 4
    return g


