    bottom = border_run(grid[-1])
    left = border_run([grid[r][0] for r in range(h)])
    right = border_run([grid[r][-1] for r in range(h)])

    # Choose whichever edge object is the long bar; the other color denotes
    # sparse markers. Each marker makes a straight ray perpendicular to the
    # long bar, reaching toward the closest edge. Preserve all bar cells.
    runs = [x for x in (top, bottom, left, right) if x]
    if not runs:
        return out
