    top = edge_segment(grid[0])
    bottom = edge_segment(grid[-1])
    left = edge_segment([grid[r][0] for r in range(h)])
    right = edge_segment([grid[r][-1] for r in range(h)])
    edge_colors = {s[0] for s in (top, bottom, left, right) if s}
    markers_colors = [c for c in counts if c != background and c not in edge_colors]
    if not markers_colors:
        return out
    marker = min(markers_colors, key=lambda c: counts[c])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # Markers aligned with an edge bar make a full ray toward that bar.
    # Markers outside a bar's span still project toward the closest matching
    # edge (this allows the sparse points to guide the opposite bars).
    for r, c in points:
        vertical_bar_hit = (left is not None and left[1] <= r <= left[2]) or \
