    """Project aligned interior markers toward their edge bar and its pair."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def segment(values):
        positions = [i for i, value in enumerate(values) if value != background]
        if not positions:
            return None
        color = values[positions[0]]
        if any(values[i] != color for i in positions):
            return None
        return color, min(positions), max(positions)

    bars = []
    for side, values in (("top", grid[0]), ("bottom", grid[-1]),
                         ("left", [grid[r][0] for r in range(h)]),
                         ("right", [grid[r][-1] for r in range(h)])):
        seg = segment(values)
        if seg:
            bars.append((side, seg))

    if len(bars) < 2:
        return out
    edge_counts = {}
    for _, (color, lo, hi) in bars:
        edge_counts[color] = edge_counts.get(color, 0) + hi - lo + 1
    bar_color = max(edge_counts, key=edge_counts.get)
    bar_objects = [(side, seg) for side, seg in bars if seg[0] == bar_color]
    marker_colors = [color for color in counts if color != background and color != bar_color]
    if not marker_colors:
        return out
    marker_color = min(marker_colors, key=lambda color: counts[color])
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color]

    # Match opposite, parallel bars. Marker coordinate within one bar's span
    # selects the same offset on the opposite bar.
    pair = None
    for side1, seg1 in bar_objects:
        for side2, seg2 in bar_objects:
            if side1 == "top" and side2 == "bottom":
                pair = ((side1, seg1), (side2, seg2), True)
            elif side1 == "left" and side2 == "right":
                pair = ((side1, seg1), (side2, seg2), False)
    if pair is None:
        return out
    first, second, horizontal_bars = pair
    segments = {first[0]: first[1], second[0]: second[1]}

    for r, c in markers:
        axis = c if horizontal_bars else r
        source_side = None
        for side, (_, lo, hi) in segments.items():
            if lo <= axis <= hi:
                source_side = side
                break
        if source_side is None:
