        # Extend the marker to its own edge bar.
        if source_side == "top":
            ray = ((rr, c) for rr in range(r - 1, 0, -1))
        elif source_side == "bottom":
            ray = ((rr, c) for rr in range(r + 1, h - 1))
        elif source_side == "left":
            ray = ((r, cc) for cc in range(c - 1, 0, -1))
        else:  # right
            ray = ((r, cc) for cc in range(c + 1, w - 1))
        for rr, cc in ray:
            if out[rr][cc] == background:
                out[rr][cc] = marker_color

        # The matching location on the opposite bar projects inward fully.
        if opposite_side == "top":
            ray = ((rr, paired_axis) for rr in range(1, h - 1))
        elif opposite_side == "bottom":
            ray = ((rr, paired_axis) for rr in range(h - 2, 0, -1))
        elif opposite_side == "left":
