 "content": "def transform(grid):
    """Each isolated marker projects to the nearest edge, leaving a 4 endpoint."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Edge bars are straight runs of a single color. Their common color is
    # structural; the sparse non-background interior color is the signal.
    def edge_run(values):
        ids = [i for i, x in enumerate(values) if x != bg]
        if not ids:
            return None
        color = values[ids[0]]
        if any(values[i] != color for i in ids):
            return None
        return color, min(ids), max(ids)

    runs = [edge_run(grid[0]), edge_run(grid[-1]),
            edge_run([grid[r][0] for r in range(h)]),
            edge_run([grid[r][-1] for r in range(h)])]
    edge_colors = {run[0] for run in runs if run}
    signal_colors = [x for x in counts if x != bg and x not in edge_colors]
    if not signal_colors:
        # For one-bar variants, use the least common non-background color.
        signal_colors = [x for x in counts if x != bg]
    if not signal_colors:
        return out
    signal = min(signal_colors, key=lambda x: counts[x])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == signal]

    # A signal point produces a ray toward the nearest border. If the ray
    # crosses other signal points, they too become highlighted endpoints.
    for r, c in points:
        distances = [(r, "up"), (h - 1 - r, "down"),
                     (c, "left"), (w - 1 - c, "right")]
        _, direction = min(distances)
        if direction == "up":
            coords = [(rr, c) for rr in range(r - 1, -1, -1)]
        elif direction == "down":
            coords = [(rr, c) for rr in range(r + 1, h)]
        elif direction == "left":
            coords = [(r, cc) for cc in range(c - 1, -1, -1)]
        else:
            coords = [(r, cc) for cc in range(c + 1, w)]
        for rr, cc in coords:
            if grid[rr][cc] == signal:
                out[rr][cc] = 4
                break
            if grid[rr][cc] == bg:
                out[rr][cc] = signal
        out[r][c] = 4

    for r, c in points:
        out[r][c] = 4
    return out


