        inds = [i for i, v in enumerate(values) if v != bg]
        if not inds:
            return None
        color = values[inds[0]]
        if any(values[i] != color for i in inds):
            return None
        return color, min(inds), max(inds)

    top = edge_segment(grid[0])
    bottom = edge_segment(grid[-1])
    left = edge_segment([grid[r][0] for r in range(h)])
    right = edge_segment([grid[r][-1] for r in range(h)])
    edge_runs = [(side, seg) for side, seg in (("top", top), ("bottom", bottom),
                  ("left", left), ("right", right)) if seg]
    if not edge_runs:
        return out

    # The single interior color distinct from border bars denotes ray color.
